            local PriorityList = Section:AddPriority("Recipe Priority", {}, {
                Values = true,
                ValueLabel = "Target",
                Default = MAX_STACK,
                Min = 0,
                Max = MAX_STACK,
            })

            S.LoadPriority = AICUI.BindCountList(PriorityList, "SMITH_RECIPES", "Target", function()
                if Browser.OnPriorityChanged then
                    Browser.OnPriorityChanged()
