	["Features/SmithingDetail.lua"] = [======[
-- SmithingDetail is the RECIPE tab of the Recipe Browser (SmithingBrowser):
-- the recipe picked in the list with its type, level or skill and stats
-- from the game's assets, whether it can be traded, what one craft needs
-- and what is missing, a popup showing what a tapped material is crafted
-- from, CRAFT NOW (a craft order in AutoSmithing, up to what the materials
-- allow) and the button that adds it to Recipe Priority or takes it out.
-- It also holds the recipe helpers the browser's list shares.
return {
    Name = "SmithingDetail",
    Dependencies = {"Runtime", "SaveConfig", "SmithingRecipes", "AutoSmithing", "Floating"},

    Start = function(Context)
        local UI = Context.UI
        local UIRef = Context.UIRef
        local CONFIG = Context.CONFIG
        local NotifyAction = Context.NotifyAction
        local Recipes = Context.SmithingRecipes
        local AutoSmithing = Context.AutoSmithing
        local Floating = Context.Floating
        local UserInputService = Context.Services.UserInputService

        local New, Stroke, Padding, List = Floating.New, Floating.Stroke, Floating.Padding, Floating.List
        local Label, Button, ClearChildren, IsInside = Floating.Label, Floating.Button, Floating.ClearChildren, Floating.IsInside

        local MAX_STACK = Context.SaveConfig.ITEM_MAX_STACK
        local ROW_HEIGHT = 34
        local POPUP_WIDTH = 240

        local Detail = {
            Name = "SmithingDetail",
            S = {
                Selected = nil,
                --// CRAFT NOW amount, kept while the details are rebuilt.
                CraftAmount = 1,
                CraftMax = 0,
                --// Material name -> its row in the details, for the popup.
                MaterialRows = {},
                DetailSignature = nil,
                PopupFor = nil,
                PopupAnchor = nil,
            },
        }

        local S = Detail.S
        local Theme, DetailScroll, Popup, PopupContent
        --// Set by Build: Select(Name) opens a recipe, Refresh() redraws
        --// the whole browser.
        local Browser
        --// Parts of the details updated in place by every refresh.
        local Craft = {}

        ------------------------------------------------------------------------
        --// What the inventory says about a recipe or a material
        ------------------------------------------------------------------------

        local function ReadInventory()
            return {
                Inventory = Recipes:GetInventory(),
                Reserves = Recipes:GetReserves(),
                Skill = Recipes:GetSkill(),
            }
        end

        local function Describe(Name, Stock)
            return Recipes:Describe({ Name = Name, Target = 0 }, Stock.Inventory, Stock.Reserves, Stock.Skill)
        end

        --// One material of one craft: Have counts the whole inventory, Usable
        --// what is left after Material Reserve, Missing what one craft lacks.
        local function DescribeMaterial(Material, Stock)
            local Have = Stock.Inventory[Material.Name] or 0
            local Keep = Stock.Reserves[Material.Name] or 0
            local Usable = math.max(0, Have - Keep)

            return {
                Have = Have,
                Keep = Keep,
                Usable = Usable,
                Missing = math.max(0, Material.Amount - Usable),
            }
        end

        --// The most CRAFT NOW may ask for: what the materials allow, and no
        --// more than the inventory can hold of the item.
        local function GetCraftMax(State)
            if not State.Known or State.Locked then
                return 0
            end

            return math.max(0, math.min(State.Craftable, MAX_STACK - State.Have))
        end

        local function IsInPriority(Name)
            for _, Entry in ipairs(CONFIG.SMITH_RECIPES or {}) do
                if Entry.Name == Name then
                    return true
                end
            end

            return false
        end

        --// The status line of a recipe and its colour.
        local function DescribeStatus(State)
            local Theme = UI.Theme

            if State.Locked then
                return "LOCKED", Theme.TextMuted
            elseif State.Craftable > 0 or not State.Short then
                return string.format("READY  x%d", State.Craftable), Theme.Cyan
            end

            return string.format("NEED %s %d/%d", State.Short.Name, State.Short.Have, State.Short.Need), Theme.Warning
        end

        --// "WEAPON  ·  LV 20  ·  BOUND": type, level (or skill) and whether
        --// it can be traded, from the assets.
        local function DescribeItem(Name)
            local Info = Recipes:GetItemInfo(Name)

            if not Info then
                return Recipes.UNKNOWN_TYPE:upper()
            end

            local Parts = { Info.Type:upper() }

            if Info.Level ~= nil then
                table.insert(Parts, "LV " .. tostring(Info.Level))
            elseif Info.Skill ~= nil then
                table.insert(Parts, "SKILL " .. tostring(Info.Skill))
            end

            if Info.Bound then
                table.insert(Parts, "BOUND")
            end

            return table.concat(Parts, "  ·  ")
        end

        --// "DMG 12  ·  DEF 3  ·  DEX 4", or nil when it has none of them.
        local function DescribeStats(Name)
            local Info = Recipes:GetItemInfo(Name)
            local Parts = {}

            for _, Stat in ipairs({ "DMG", "DEF", "DEX" }) do
                if Info and Info[Stat] ~= nil then
                    table.insert(Parts, Stat .. " " .. tostring(Info[Stat]))
                end
            end

            return #Parts > 0 and table.concat(Parts, "  ·  ") or nil
        end

        Detail.ReadInventory = ReadInventory
        Detail.Describe = Describe
        Detail.GetCraftMax = GetCraftMax
        Detail.IsInPriority = IsInPriority
        Detail.DescribeStatus = DescribeStatus
        Detail.DescribeItem = DescribeItem

        ------------------------------------------------------------------------
        --// Material popup
        ------------------------------------------------------------------------

        local function HidePopup()
            S.PopupFor = nil
            S.PopupAnchor = nil

            if Popup then
                Popup.Visible = false
            end
        end

        --// Beside the tapped row, flipped to its left when it would run off
        --// the screen, then pulled inside once its height is known.
        --// Deferred: a row just rebuilt has no position until layout runs.
        local function PlacePopup(Anchor)
            task.defer(function()
                if not Popup.Visible or S.PopupAnchor ~= Anchor or not Anchor.Parent then
                    return
                end

                local Screen = UI.ScreenGui.AbsoluteSize
                local Left = Anchor.AbsolutePosition.X + Anchor.AbsoluteSize.X + 6

                if Left + POPUP_WIDTH > Screen.X - Floating.SCREEN_MARGIN then
                    Left = Anchor.AbsolutePosition.X - POPUP_WIDTH - 6
                end

                Popup.Position = UDim2.fromOffset(Left, Anchor.AbsolutePosition.Y)
                UI._ClampToParent(Popup)
            end)
        end

        local function ShowPopup(MaterialName, Anchor)
            local Stock = ReadInventory()
            local Recipe = Recipes:Get(MaterialName)
            local Have = Stock.Inventory[MaterialName] or 0
            local Keep = Stock.Reserves[MaterialName] or 0

            ClearChildren(PopupContent)

            local Header = New("Frame", { Parent = PopupContent, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 20), LayoutOrder = 1 })
            Label(Header, MaterialName, 12, { Size = UDim2.new(1, -24, 1, 0), TextColor3 = Theme.Cyan, Font = Floating.Fonts.Bold })

            local Close = Button(Header, "×", Theme.Danger, {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, 0, 0.5, 0),
                Size = UDim2.fromOffset(20, 18),
            })
            UI:_Connect(Close.Activated, HidePopup)

            local HaveText = string.format("HAVE  %d", Have)

            if Keep > 0 then
                HaveText ..= string.format("   (KEEP %d)", Keep)
            end

            Label(PopupContent, HaveText, 9, { TextColor3 = Theme.TextSecondary, LayoutOrder = 2 })

            if not Recipe then
                Label(PopupContent, "Not craftable: no smithing recipe makes it", 9, {
                    TextColor3 = Theme.TextMuted,
                    TextWrapped = true,
                    TextTruncate = Enum.TextTruncate.None,
                    AutomaticSize = Enum.AutomaticSize.Y,
                    LayoutOrder = 3,
                })
            else
                local Locked = Recipe.Skill > Stock.Skill

                Label(PopupContent, string.format("CRAFTED FROM  ·  SKILL %s", tostring(Recipe.Skill)), 9, {
                    TextColor3 = Locked and Theme.Danger or Theme.TextSecondary,
                    LayoutOrder = 3,
                })

                for Index, Material in ipairs(Recipe.Materials) do
                    local Info = DescribeMaterial(Material, Stock)

                    Label(PopupContent, string.format("  %s   %d / %d", Material.Name, Info.Usable, Material.Amount), 9, {
                        TextColor3 = Info.Missing > 0 and Theme.Warning or Theme.Text,
                        LayoutOrder = 3 + Index,
                    })
                end

                local Open = Button(PopupContent, "OPEN RECIPE", Theme.Cyan, { LayoutOrder = 100, Size = UDim2.new(1, 0, 0, 22) })

                UI:_Connect(Open.Activated, function()
                    Browser:Select(MaterialName)
                end)
            end

            S.PopupFor = MaterialName
            S.PopupAnchor = Anchor
            Popup.Visible = true
            PlacePopup(Anchor)
        end

        ------------------------------------------------------------------------
        --// RECIPE tab: details and CRAFT NOW
        ------------------------------------------------------------------------

        local function GetDetailSignature(Recipe, Stock)
            local Parts = { Recipe.Name, tostring(Stock.Skill), tostring(Stock.Inventory[Recipe.Name] or 0), tostring(IsInPriority(Recipe.Name)) }

            for _, Material in ipairs(Recipe.Materials) do
                local Info = DescribeMaterial(Material, Stock)
                table.insert(Parts, Material.Name .. ":" .. Info.Have .. ":" .. Info.Keep)
            end

            return table.concat(Parts, "|")
        end

        local function AddMaterialRow(Material, Stock, Order)
            local Info = DescribeMaterial(Material, Stock)
            local Craftable = Recipes:Get(Material.Name) ~= nil

            local Row = New("TextButton", {
                Parent = DetailScroll,
                Size = UDim2.new(1, -6, 0, ROW_HEIGHT),
                BackgroundColor3 = Theme.Element,
                BorderSizePixel = 0,
                Text = "",
                AutoButtonColor = false,
                LayoutOrder = Order,
            })

            local RowStroke = Stroke(Row, Info.Missing > 0 and Theme.Warning or Theme.BorderDim, Info.Missing > 0 and 0.4 or 0.3)
            Floating.Hover(Row, RowStroke)

            Label(Row, Material.Name .. (Craftable and "  ›" or ""), 10, {
                Position = UDim2.fromOffset(8, 3),
                Size = UDim2.new(1, -90, 0, 15),
            })

            Label(Row, string.format("%d / %d", Info.Usable, Material.Amount), 10, {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, -8, 0, 3),
                Size = UDim2.fromOffset(80, 15),
                TextXAlignment = Enum.TextXAlignment.Right,
                TextColor3 = Info.Missing > 0 and Theme.Warning or Theme.Cyan,
            })

            local Note = Info.Missing > 0 and string.format("MISSING %d", Info.Missing) or "OK"

            if Info.Keep > 0 then
                Note ..= string.format("   ·   HAVE %d, KEEP %d", Info.Have, Info.Keep)
            end

            Label(Row, Note, 10, {
                Position = UDim2.fromOffset(8, 18),
                Size = UDim2.new(1, -16, 0, 13),
                TextColor3 = Info.Missing > 0 and Theme.Warning or Theme.TextMuted,
            })

            UI:_Connect(Row.Activated, function()
                if S.PopupFor == Material.Name then
                    HidePopup()
                else
                    ShowPopup(Material.Name, Row)
                end
            end)

            S.MaterialRows[Material.Name] = Row
        end

        local function TogglePriority(Name)
            local RecipeList = UIRef.RecipePriorityComponent

            if not RecipeList then
                return
            end

            if IsInPriority(Name) then
                RecipeList:Remove(Name)
                NotifyAction("AUTO SMITHING", "Removed " .. Name)
            elseif RecipeList:Add(Name, MAX_STACK) then
                NotifyAction("AUTO SMITHING", "Added " .. Name)
            end

            Browser:Refresh()
        end

        --// Clamped to what can be crafted; at least 1 whenever any can.
        local function SetCraftAmount(Value)
            local Amount = math.clamp(math.floor(tonumber(Value) or 0), math.min(1, S.CraftMax), S.CraftMax)
            S.CraftAmount = Amount

            if Craft.Slider then
                Craft.Slider:Set(Amount, false)
            end

            if Craft.AmountBox then
                Craft.AmountBox.Text = tostring(Amount)
            end
        end

        local function StartCraft(Name)
            if S.CraftMax < 1 then
                NotifyAction("CRAFT NOW", Name .. ": nothing to craft with (locked, missing materials or a full stack)")
                return
            end

            local Amount = math.clamp(S.CraftAmount, 1, S.CraftMax)

            if AutoSmithing:StartOrder(Name, Amount) then
                NotifyAction("CRAFT NOW", string.format("Crafting %d x %s", Amount, Name))
                Browser:Refresh()
            end
        end

        --// The order line and CANCEL under CRAFT NOW, kept current.
        local function RefreshOrderLine()
            if not Craft.OrderLabel or not Craft.OrderLabel.Parent then
                return
            end

            local Order = AutoSmithing:GetOrder()

            Craft.OrderLabel.Text = Order
                and string.format("ORDER  %s  %d / %d", Order.Name, Order.Done, Order.Count)
                or "NO CRAFT ORDER RUNNING"
            Craft.OrderLabel.TextColor3 = Order and Theme.Cyan or Theme.TextMuted
            Craft.CancelButton.Visible = Order ~= nil
        end

        local function BuildCraftPanel(Recipe, State, Order)
            S.CraftMax = GetCraftMax(State)

            local Panel = New("Frame", {
                Parent = DetailScroll,
                Size = UDim2.new(1, -6, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundColor3 = Theme.Element,
                BorderSizePixel = 0,
                LayoutOrder = Order,
            })

            Panel.BackgroundTransparency = 0.1
            Stroke(Panel, Theme.BorderDim, 0.25)
            Padding(Panel, 8, 8)
            List(Panel, 5)

            Label(Panel, string.format("CRAFT NOW  ·  UP TO %d", S.CraftMax), 10, {
                TextColor3 = S.CraftMax > 0 and Theme.Cyan or Theme.TextMuted,
                Font = Floating.Fonts.Bold,
                LayoutOrder = 1,
            })

            local SliderSection = Floating.Section(Panel, { LayoutOrder = 2 })

            Craft.Slider = SliderSection:AddSlider{
                Name = "Amount",
                Default = 0,
                Min = 0,
                Max = math.max(1, S.CraftMax),
                Callback = function(Value)
                    SetCraftAmount(Value)
                end,
            }

            local Controls = New("Frame", { Parent = Panel, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 26), LayoutOrder = 3 })

            Craft.AmountBox = New("TextBox", {
                Parent = Controls,
                Size = UDim2.fromOffset(64, 26),
                BackgroundColor3 = Theme.PanelLight,
                BorderSizePixel = 0,
                Text = "",
                PlaceholderText = "amount",
                PlaceholderColor3 = Theme.TextMuted,
                TextColor3 = Theme.Text,
                TextSize = 10,
                Font = Floating.Fonts.Bold,
                ClearTextOnFocus = false,
            })

            Floating.Hover(Craft.AmountBox, Stroke(Craft.AmountBox, Theme.BorderDim, 0.15))

            local MaxButton = Button(Controls, "MAX", Theme.Text, {
                Position = UDim2.fromOffset(70, 0),
                Size = UDim2.fromOffset(52, 26),
            })

            local CraftButton = Button(Controls, "CRAFT", S.CraftMax > 0 and Theme.Cyan or Theme.TextMuted, {
                Position = UDim2.fromOffset(128, 0),
                Size = UDim2.new(1, -128, 0, 26),
            })

            local OrderRow = New("Frame", { Parent = Panel, BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 22), LayoutOrder = 4 })
            Craft.OrderLabel = Label(OrderRow, "", 9, { Size = UDim2.new(1, -76, 1, 0) })
            Craft.CancelButton = Button(OrderRow, "CANCEL", Theme.Danger, {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, 0, 0, 0),
                Size = UDim2.fromOffset(70, 22),
            })

            UI:_Connect(Craft.AmountBox.FocusLost, function()
                SetCraftAmount(Craft.AmountBox.Text)
            end)

            UI:_Connect(MaxButton.Activated, function()
                SetCraftAmount(S.CraftMax)
            end)

            UI:_Connect(CraftButton.Activated, function()
                StartCraft(Recipe.Name)
            end)

            UI:_Connect(Craft.CancelButton.Activated, function()
                AutoSmithing:CancelOrder()
                RefreshOrderLine()
            end)

            SetCraftAmount(S.CraftAmount)
            RefreshOrderLine()
        end

        local function BuildDetail(Recipe, Stock)
            ClearChildren(DetailScroll)
            table.clear(S.MaterialRows)
            table.clear(Craft)

            if not Recipe then
                Label(DetailScroll, "Pick a recipe from the list", 10, { TextColor3 = Theme.TextMuted, LayoutOrder = 1 })
                return
            end

            local State = Describe(Recipe.Name, Stock)
            local Status, StatusColor = DescribeStatus(State)
            local Info = Recipes:GetItemInfo(Recipe.Name)
            local Stats = DescribeStats(Recipe.Name)

            Label(DetailScroll, "◇  " .. string.upper(Recipe.Name), 13, { TextColor3 = Theme.Cyan, Font = Floating.Fonts.Bold, LayoutOrder = 1 })
            Label(DetailScroll, DescribeItem(Recipe.Name) .. ((Info and not Info.Bound) and "  ·  TRADEABLE" or ""), 9, {
                TextColor3 = (Info and Info.Bound) and Theme.Warning or Theme.TextSecondary,
                LayoutOrder = 2,
            })

            if Stats then
                Label(DetailScroll, Stats, 10, { TextColor3 = Theme.Text, LayoutOrder = 3 })
            end

            Label(DetailScroll, string.format("SMITHING SKILL  %s  ·  YOURS  %s  ·  HAVE  %d", tostring(Recipe.Skill), tostring(Stock.Skill), State.Have), 9, {
                TextColor3 = State.Locked and Theme.Danger or Theme.TextSecondary,
                LayoutOrder = 4,
            })
            Label(DetailScroll, Status, 10, { TextColor3 = StatusColor, Font = Floating.Fonts.Bold, LayoutOrder = 5 })
            Label(DetailScroll, "MATERIALS PER CRAFT  (tap one to see how it is made)", 10, {
                TextColor3 = Theme.TextMuted,
                LayoutOrder = 6,
            })

            if #Recipe.Materials == 0 then
                Label(DetailScroll, "  none", 9, { TextColor3 = Theme.TextMuted, LayoutOrder = 7 })
            end

            for Index, Material in ipairs(Recipe.Materials) do
                AddMaterialRow(Material, Stock, 6 + Index)
            end

            BuildCraftPanel(Recipe, State, 500)

            local InPriority = IsInPriority(Recipe.Name)
            local Toggle = Button(DetailScroll, InPriority and "REMOVE FROM RECIPE PRIORITY" or "ADD TO RECIPE PRIORITY",
                InPriority and Theme.Danger or Theme.Cyan, { Size = UDim2.new(1, -6, 0, 26), LayoutOrder = 1000 })

            UI:_Connect(Toggle.Activated, function()
                TogglePriority(Recipe.Name)
            end)
        end

        --// Rebuilt only when something it shows changed, so a refresh does
        --// not reset the scroll or drop an open popup.
        local function RefreshDetail(Stock)
            local Recipe = S.Selected and Recipes:Get(S.Selected)

            if S.Selected and not Recipe then
                S.Selected = nil
            end

            local Signature = Recipe and GetDetailSignature(Recipe, Stock) or ""

            if Signature == S.DetailSignature then
                RefreshOrderLine()
                return
            end

            S.DetailSignature = Signature
            BuildDetail(Recipe, Stock)

            --// The popup's row was replaced: follow the new one, or close.
            if S.PopupFor then
                local Anchor = S.MaterialRows[S.PopupFor]

                if Anchor then
                    ShowPopup(S.PopupFor, Anchor)
                else
                    HidePopup()
                end
            end
        end

        local function BuildPopup()
            Popup = New("TextButton", {
                --// A button, so a click on it stops here instead of reaching the UI
                --// underneath; it draws like a frame.
                Text = "",
                AutoButtonColor = false,
                Name = "SmithingBrowserPopup",
                Parent = UI.ScreenGui,
                Size = UDim2.fromOffset(POPUP_WIDTH, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundColor3 = Theme.Panel,
                BorderSizePixel = 0,
                Active = true,
                Visible = false,
                ZIndex = Floating.POPUP_Z,
            })

            Stroke(Popup, Theme.CyanDark, 0.1)
            Padding(Popup, 8, 8)

            PopupContent = New("Frame", {
                Parent = Popup,
                BackgroundTransparency = 1,
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
            })

            List(PopupContent, 3)

            --// A tap anywhere but the popup or its row closes the popup.
            UI:_Connect(UserInputService.InputBegan, function(Input)
                if not Popup.Visible
                    or (Input.UserInputType ~= Enum.UserInputType.MouseButton1
                        and Input.UserInputType ~= Enum.UserInputType.Touch)
                then
                    return
                end

                local Position = Vector2.new(Input.Position.X, Input.Position.Y)

                if not IsInside(Popup, Position) and not IsInside(S.PopupAnchor, Position) then
                    HidePopup()
                end
            end)
        end

        ------------------------------------------------------------------------
        --// API (for SmithingBrowser)
        ------------------------------------------------------------------------

        --// Builds the tab into Scroll. Owner is the browser: Owner:Select(Name)
        --// opens a recipe, Owner:Refresh() redraws the window.
        function Detail:Build(Scroll, Owner)
            Theme = UI.Theme
            DetailScroll = Scroll
            Browser = Owner
            BuildPopup()
        end

        function Detail:Refresh(Stock)
            RefreshDetail(Stock)
        end

        function Detail:Select(Name)
            S.Selected = Name
            S.DetailSignature = nil
            S.CraftAmount = 1
            HidePopup()
        end

        function Detail:GetSelected()
            return S.Selected
        end

        --// Rebuilt on the next refresh even when nothing it shows changed.
        function Detail:Invalidate()
            S.DetailSignature = nil
        end

        function Detail:HidePopup()
            HidePopup()
        end

        return Detail
    end,
}
]======],
	["Features/SmithingMinigame.lua"] = [======[
-- SmithingMinigame plays the strike minigame the game opens after
-- CraftingStart: PlayerGui.CraftingGame.Main holds a moving line (Mover), a
-- target band (ClickArea) and the strike button (Action); Success or Failed
-- becomes visible when the round is over.
--
-- While running it checks every rendered frame and strikes when Mover reaches
-- ClickArea. The strike is only pressed while the mover's centre is inside the
-- band on the frame the strike is decided on and on the frame the click lands
-- on: a direct click (firesignal / getconnections) is run at once, a synthetic
-- one on the mouse release a few frames later, and either way the press has to
-- land inside the band. Pressing as soon as the mover's leading edge touches
-- the band presses before the mover has arrived, and a speed measured across
-- the game's reset can throw the check past the band as well, so neither is
-- struck on.
--
-- The speed is only ever measured between two frames of the same sweep. The
-- game resets Mover for the next strike, so the frame just before and the
-- frame just after a strike (or after the minigame window comes and goes) are
-- not two samples of one movement: the reset itself would read as speed. Those
-- frames only take the sample, and the speed goes with them, so the prediction
-- of a later frame is never made from a reset.
return {
    Name = "SmithingMinigame",
    Dependencies = {"Runtime", "GuiClick"},

    Start = function(Context)
        local Player = Context.Player
        local RunService = Context.Services.RunService
        local GuiClick = Context.GuiClick

        --// Pixels of slack around ClickArea, as in the proof of concept. It
        --// is given to the frame the click lands on, never to the frame the
        --// strike is decided on, so it cannot make a strike early.
        local STRIKE_PADDING = 1
        --// Never strike twice within this, so one overlap is one strike.
        local STRIKE_COOLDOWN = 0.12
        --// The strike button listens to this signal.
        local STRIKE_SIGNALS = { "MouseButton1Click" }

        local Minigame = {
            Name = "SmithingMinigame",
            S = {
                Connection = nil,
                LastStrike = 0,
                Strikes = 0,
                LastMoverPosition = nil,
                MoverVelocity = Vector2.zero,
                --// The click method that worked last; firesignal is what
                --// the proof of concept used.
                Method = "firesignal",
            },
        }

        local S = Minigame.S

        --// CraftingGame.Main, or nil while the minigame is not open.
        function Minigame:Find()
            local PlayerGui = Player:FindFirstChild("PlayerGui")
            local CraftingGame = PlayerGui and PlayerGui:FindFirstChild("CraftingGame")
            return CraftingGame and CraftingGame:FindFirstChild("Main")
        end

        --// "Success", "Failed", or nil while the round is still running.
        function Minigame:GetResult(Main)
            local Success = Main:FindFirstChild("Success")
            local Failed = Main:FindFirstChild("Failed")

            if Success and Success.Visible then
                return "Success"
            elseif Failed and Failed.Visible then
                return "Failed"
            end

            return nil
        end

        function Minigame:GetStrikes()
            return S.Strikes
        end

        --// Whether the mover has reached the band, with Slack pixels of room
        --// to spare. Along the bar it is the mover's centre that counts, not
        --// the edge that arrives first, so a strike is never pressed before
        --// the mover is at the band; the two still have to meet across it.
        local function Inside(Mover, Position, Band, Slack)
            local Size = Mover.AbsoluteSize
            local BandPosition = Band.AbsolutePosition
            local BandSize = Band.AbsoluteSize

            local CentreX = Position.X + Size.X / 2

            return CentreX >= BandPosition.X - Slack
                and CentreX <= BandPosition.X + BandSize.X + Slack
                and Position.Y < BandPosition.Y + BandSize.Y + Slack
                and Position.Y + Size.Y + Slack > BandPosition.Y
        end

        --// Forgets the mover's motion. Used wherever the next frame is not
        --// the continuation of the last one: the round ended, the minigame
        --// window came or went, or a strike was just pressed and the game is
        --// resetting the mover for the next strike.
        local function ForgetMover()
            S.LastMoverPosition = nil
            S.MoverVelocity = Vector2.zero
        end

        local function Step(DeltaTime)
            local Main = Minigame:Find()

            if not Main or Minigame:GetResult(Main) then
                ForgetMover()
                return
            end

            local ClickArea = Main:FindFirstChild("ClickArea")
            local Mover = Main:FindFirstChild("Mover")
            local Action = Main:FindFirstChild("Action")

            if not ClickArea or not Mover or not Action then
                ForgetMover()
                return
            end

            local Position = Mover.AbsolutePosition
            local Previous = S.LastMoverPosition
            S.LastMoverPosition = Position

            --// Without a frame before it there is no movement to measure, so
            --// this frame only takes the sample, and never strikes: it may be
            --// the frame the mover was reset on.
            if not Previous or DeltaTime <= 0 then
                S.MoverVelocity = Vector2.zero
                return
            end

            S.MoverVelocity = (Position - Previous) / DeltaTime

            local now = os.clock()

            if now - S.LastStrike < STRIKE_COOLDOWN then
                return
            end

            --// Where the mover will be when the click lands. The centre has
            --// to be inside the band there as well as on this frame, so the
            --// press cannot be early however the click is delivered, and a
            --// speed measured across a reset cannot strike on its own.
            local CheckPosition = Position + S.MoverVelocity * DeltaTime

            if not Inside(Mover, Position, ClickArea, 0)
                or not Inside(Mover, CheckPosition, ClickArea, STRIKE_PADDING) then
                return
            end

            --// Before the click: a synthetic click yields, and later frames
            --// run meanwhile and would strike again.
            S.LastStrike = now

            local Method = GuiClick.Click(Action, S.Method, STRIKE_SIGNALS)

            if Method then
                S.Method = Method
                S.Strikes += 1
            end

            --// The next strike is measured from the next strike's mover, not
            --// from the movement of the one just struck.
            ForgetMover()
        end

        --// Starts playing; idempotent. Runs on RenderStepped, where the GUI
        --// has its final position for the frame.
        function Minigame:Start()
            if S.Connection then
                return
            end

            S.Strikes = 0
            S.LastStrike = 0
            S.LastMoverPosition = nil
            S.MoverVelocity = Vector2.zero
            S.Connection = RunService.RenderStepped:Connect(Step)
        end

        function Minigame:Stop()
            if S.Connection then
                S.Connection:Disconnect()
                S.Connection = nil
            end
        end

        Context.Lifetime.OnEnd(function()
            Minigame:Stop()
        end)

        return Minigame
    end,
}
]======],
	["Features/SmithingRecipes.lua"] = [======[
-- SmithingRecipes reads the game's crafting recipes and answers what can be
-- crafted right now. Shared by AutoSmithing (which recipe to craft next, and
-- what each recipe in its Recipe Status list is waiting on).
--
-- A recipe is a child of ReplicatedStorage.CraftingRecipes holding
--   CraftingSkill  the SmithingSkill a player needs to craft it
--   CraftType      the kind of craft
--   <Material>     a number value per material: how many one craft uses
-- The crafted item is assumed to be named like the recipe ("Iron Ingot").
--
-- What an item is comes from the game's assets, Commons.getAssets(true)
-- from CoreCommons: Assets[Name].Value is its type, and its children
-- LVL, Skill, DMG, DEF and DEX its stats. A Bound child means it cannot
-- be traded.
return {
    Name = "SmithingRecipes",
    Dependencies = {"Runtime", "SaveConfig"},

    Start = function(Context)
        local Player = Context.Player
        local Replicated = Context.Services.Replicated
        local CONFIG = Context.CONFIG

        local SKILL_STAT = "SmithingSkill"
        --// Recipe children that are settings rather than materials.
        local NON_MATERIALS = { CraftType = true, CraftingSkill = true }
        --// Assets that could not be read are tried again after this long.
        local ASSETS_RETRY_SECONDS = 10
        --// An item with no type in the assets is filed under this.
        local UNKNOWN_TYPE = "Other"

        local Recipes = {
            Name = "SmithingRecipes",
            UNKNOWN_TYPE = UNKNOWN_TYPE,
            S = {
                --// Recipe name -> parsed recipe; nil until read, and dropped
                --// whenever the recipe folder changes.
                Cache = nil,
                Folder = nil,
                Connections = {},
                Assets = nil,
                AssetsRetryAt = 0,
                --// Item name -> GetItemInfo result (false when not an asset).
                ItemInfo = {},
            },
        }

        local S = Recipes.S

        local function GetAssets()
            if S.Assets or os.clock() < S.AssetsRetryAt then
                return S.Assets
            end

            local Module = Replicated:FindFirstChild("CoreCommons", true)
            local Ok, Assets = pcall(function()
                local Commons = Module and require(Module)
                return Commons and Commons.getAssets and Commons.getAssets(true)
            end)

            if Ok and type(Assets) == "table" then
                S.Assets = Assets
                table.clear(S.ItemInfo)
            else
                S.AssetsRetryAt = os.clock() + ASSETS_RETRY_SECONDS

                if not S.WarnedAssets then
                    S.WarnedAssets = true
                    warn("[SmithingRecipes] Could not read the game's assets:", Assets)
                end
            end

            return S.Assets
        end

        --// The game's assets (item name -> asset), or nil while they cannot
        --// be read. Shared with the Asset Explorer.
        function Recipes:GetAssets()
            return GetAssets()
        end

        --// An asset is an Instance with value children; a plain table of the
        --// same shape is read the same way.
        local function GetChild(Asset, ChildName)
            if typeof(Asset) == "Instance" then
                return Asset:FindFirstChild(ChildName)
            end

            return type(Asset) == "table" and Asset[ChildName] or nil
        end

        --// The Value of a child of Asset, or nil when it has none.
        local function ReadChild(Asset, ChildName)
            local Child = GetChild(Asset, ChildName)

            if not Child then
                return nil
            end

            local Ok, Value = pcall(function()
                return Child.Value
            end)

            return Ok and Value or nil
        end

        local function ReadItemInfo(Asset)
            local Ok, Type = pcall(function()
                return Asset.Value
            end)

            Type = Ok and Type ~= nil and tostring(Type) or ""

            return {
                Type = Type ~= "" and Type or UNKNOWN_TYPE,
                Level = ReadChild(Asset, "LVL"),
                Skill = ReadChild(Asset, "Skill"),
                DMG = ReadChild(Asset, "DMG"),
                DEF = ReadChild(Asset, "DEF"),
                DEX = ReadChild(Asset, "DEX"),
                Bound = GetChild(Asset, "Bound") ~= nil,
            }
        end

        --// What the game's assets say about an item: { Type, Level, Skill,
        --// DMG, DEF, DEX, Bound }, the stats nil when it has none. Nil when
        --// the item is not in the assets or they cannot be read.
        function Recipes:GetItemInfo(Name)
            local Cached = S.ItemInfo[Name]

            if Cached ~= nil then
                return Cached or nil
            end

            local Assets = GetAssets()

            if not Assets then
                return nil
            end

            local Asset = Assets[Name]
            local IsAsset = typeof(Asset) == "Instance" or type(Asset) == "table"
            local Info = IsAsset and ReadItemInfo(Asset) or false

            S.ItemInfo[Name] = Info
            return Info or nil
        end

        --// The item's type for filtering; UNKNOWN_TYPE when it has none.
        function Recipes:GetItemType(Name)
            local Info = self:GetItemInfo(Name)
            return Info and Info.Type or UNKNOWN_TYPE
        end

        local function ReadRecipe(Recipe)
            local Skill = Recipe:FindFirstChild("CraftingSkill")
            local CraftType = Recipe:FindFirstChild("CraftType")

            if not Skill or not CraftType then
                return nil
            end

            local Materials = {}

            for _, Child in ipairs(Recipe:GetChildren()) do
                if not NON_MATERIALS[Child.Name]
                    and (Child:IsA("NumberValue") or Child:IsA("IntValue"))
                    and Child.Value > 0
                then
                    table.insert(Materials, { Name = Child.Name, Amount = Child.Value })
                end
            end

            table.sort(Materials, function(A, B)
                return A.Name < B.Name
            end)

            return {
                Name = Recipe.Name,
                CraftType = tostring(CraftType.Value),
                Skill = tonumber(Skill.Value) or 0,
                Materials = Materials,
            }
        end

        --// Watches the folder so a recipe added or removed (or the folder
        --// being replaced) is read again on the next question.
        local function GetCache()
            local Folder = Replicated:FindFirstChild("CraftingRecipes")

            if Folder ~= S.Folder then
                for _, Connection in ipairs(S.Connections) do
                    Connection:Disconnect()
                end

                table.clear(S.Connections)
                S.Folder = Folder
                S.Cache = nil

                if Folder then
                    local function Invalidate()
                        S.Cache = nil
                    end

                    table.insert(S.Connections, Folder.ChildAdded:Connect(Invalidate))
                    table.insert(S.Connections, Folder.ChildRemoved:Connect(Invalidate))
                end
            end

            if not S.Cache then
                S.Cache = {}

                for _, Recipe in ipairs(Folder and Folder:GetChildren() or {}) do
                    local Parsed = ReadRecipe(Recipe)

                    if Parsed then
                        S.Cache[Parsed.Name] = Parsed
                    end
                end
            end

            return S.Cache
        end

        function Recipes:Get(Name)
            return GetCache()[Name]
        end

        --// Every recipe, easiest first.
        function Recipes:GetAll()
            local List = {}

            for _, Recipe in pairs(GetCache()) do
                table.insert(List, Recipe)
            end

            table.sort(List, function(A, B)
                if A.Skill ~= B.Skill then
                    return A.Skill < B.Skill
                end

                return A.Name < B.Name
            end)

            return List
        end

        --// Every material any recipe uses, sorted.
        function Recipes:GetMaterialNames()
            local Seen = {}
            local Names = {}

            for _, Recipe in pairs(GetCache()) do
                for _, Material in ipairs(Recipe.Materials) do
                    if not Seen[Material.Name] then
                        Seen[Material.Name] = true
                        table.insert(Names, Material.Name)
                    end
                end
            end

            table.sort(Names)
            return Names
        end

        function Recipes:GetSkillValue()
            local PlayerStats = Player:FindFirstChild("PlayerStats")
            return PlayerStats and PlayerStats:FindFirstChild(SKILL_STAT)
        end

        function Recipes:GetSkill()
            local Skill = self:GetSkillValue()
            return Skill and tonumber(Skill.Value) or 0
        end

        function Recipes:GetInventoryText()
            local PlayerStats = Player:FindFirstChild("PlayerStats")
            local Inventory = PlayerStats and PlayerStats:FindFirstChild("Inventory")
            return Inventory and Inventory.Value or ""
        end

        --// Item name -> count, from the "Name|Amount,Name|Amount" string.
        function Recipes:GetInventory()
            local Counts = {}

            for Item in string.gmatch(self:GetInventoryText(), "([^,]+)") do
                local Name, Amount = string.match(Item, "([^|]+)|(.+)")

                if Name then
                    Counts[Name] = tonumber(Amount) or 0
                end
            end

            return Counts
        end

        --// Material name -> how many Material Reserve keeps back.
        function Recipes:GetReserves()
            local Reserves = {}

            for _, Entry in ipairs(CONFIG.SMITH_RESERVES or {}) do
                Reserves[Entry.Name] = tonumber(Entry.Keep) or 0
            end

            return Reserves
        end

        --// Where one recipe of the list stands:
        --//   Known      the game has this recipe
        --//   Locked     SmithingSkill is below its requirement
        --//   Have / Target / Remaining  of the crafted item
        --//   Craftable  crafts the materials allow, after the reserves
        --//   Short      the first material holding it back { Name, Have, Need }
        function Recipes:Describe(Entry, Inventory, Reserves, Skill)
            local Recipe = self:Get(Entry.Name)
            local Have = Inventory[Entry.Name] or 0
            local Target = tonumber(Entry.Target) or 0
            local State = {
                Name = Entry.Name,
                Recipe = Recipe,
                Known = Recipe ~= nil,
                Have = Have,
                Target = Target,
                Remaining = math.max(0, Target - Have),
                Skill = Skill,
                Locked = false,
                Craftable = 0,
                Short = nil,
            }

            if not Recipe then
                return State
            end

            State.Locked = Recipe.Skill > Skill

            local Craftable = math.huge

            for _, Material in ipairs(Recipe.Materials) do
                local Usable = math.max(0, (Inventory[Material.Name] or 0) - (Reserves[Material.Name] or 0))
                local Count = math.floor(Usable / Material.Amount)

                if Count < Craftable then
                    Craftable = Count
                end

                if Count < 1 and not State.Short then
                    State.Short = { Name = Material.Name, Have = Usable, Need = Material.Amount }
                end
            end

            State.Craftable = Craftable == math.huge and State.Remaining or Craftable
            return State
        end

        --// Every recipe in the Recipe Priority list, in order.
        function Recipes:GetPlan()
            local Inventory = self:GetInventory()
            local Reserves = self:GetReserves()
            local Skill = self:GetSkill()
            local Plan = {}

            for _, Entry in ipairs(CONFIG.SMITH_RECIPES or {}) do
                table.insert(Plan, self:Describe(Entry, Inventory, Reserves, Skill))
            end

            return Plan
        end

        --// The first recipe in priority that can be crafted now and is not
        --// done, skipping any IsPaused(Name) reports. Also returns the plan.
        function Recipes:PickNext(IsPaused)
            local Plan = self:GetPlan()

            for _, State in ipairs(Plan) do
                if State.Known
                    and not State.Locked
                    and State.Remaining > 0
                    and State.Craftable > 0
                    and not IsPaused(State.Name)
                then
                    return State, Plan
                end
            end

            return nil, Plan
        end

        Context.Lifetime.OnEnd(function()
            Context.Lifetime.Disconnect(S.Connections)
        end)

        return Recipes
    end,
}
